SELECT r.route_id, r.route_no, r.route_name, r.product_id, r.product_code, r.product_name, r.version, r.status, r.audit_by, r.audit_time, r.audit_remark, r.total_std_time, r.del_flag, r.create_by, r.create_time, r.update_by, r.update_time, r.remark, (SELECT COUNT(*) FROM mms_route_process rp WHERE rp.route_id = r.route_id AND rp.del_flag = '0') AS process_count FROM mms_route r
r.del_flag = '0' AND r.route_no LIKE CONCAT('%', #{routeNo}, '%') AND r.route_name LIKE CONCAT('%', #{routeName}, '%') AND r.product_id = #{productId} AND r.product_code LIKE CONCAT('%', #{productCode}, '%') AND r.product_name LIKE CONCAT('%', #{productName}, '%') AND r.version LIKE CONCAT('%', #{version}, '%') AND r.status = #{status} AND date(r.create_time) >= #{params.beginTime} AND date(r.create_time) <= #{params.endTime}
ORDER BY r.route_id DESC

