INSERT INTO mms_route (
    route_no, route_name, product_id, product_code, product_name, version,
    status, audit_by, audit_time, total_std_time,
    del_flag, create_by, create_time, update_by, update_time, remark
)VALUES(
    #{routeNo}, #{routeName}, #{productId}, #{productCode}, #{productName}, #{version},
    #{status}, #{auditBy}, #{auditTime}, #{totalStdTime},
    #{delFlag}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{remark}
)

INSERT INTO mms_route_process (
    route_id, process_id, process_code, process_name, resource_id, resource_name, step_seq,
    std_time, prep_time, is_key_process, is_outsource,
    del_flag, create_by, create_time, update_by, update_time, remark
)VALUES(
    #{routeId}, #{processId}, #{processCode}, #{processName}, #{resourceId}, #{resourceName}, #{stepSeq},
    #{stdTime}, #{prepTime}, #{isKeyProcess}, #{isOutsource},
    #{delFlag}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{remark}
)

INSERT INTO mms_route_version_log (
    route_id, route_no, old_version, new_version, old_status, new_status,
    change_type, change_desc, audit_remark, change_by, change_time
)VALUES(
    #{routeId}, #{routeNo}, #{oldVersion}, #{newVersion}, #{oldStatus}, #{newStatus},
    #{changeType}, #{changeDesc}, #{auditRemark}, #{changeBy}, #{changeTime}
)
